local SpurMaker = {}
local PRODUCTS = {
    iron_spurs = { name = "Železni ostroge", ironCost = 1, time = 1, cost = 12, cavalryBoost = 4, durability = 18, description = "Preproste železne ostroge za konjenico." },
    steel_spurs = { name = "Jeklene ostroge", steelCost = 1, time = 2, cost = 35, cavalryBoost = 7, durability = 25, prestige = 1, description = "Jeklene ostroge z močnim učinkom." },
    brass_spurs = { name = "Medeninaste ostroge", brassCost = 1, time = 3, cost = 80, cavalryBoost = 9, durability = 30, prestige = 2, description = "Medeninaste ostroge z okrasjem." },
    silver_rowel_spurs = { name = "Srebrne zvezdne ostroge", silverCost = 1, brassCost = 1, time = 5, cost = 200, cavalryBoost = 13, durability = 40, prestige = 5, happiness = 1, description = "Ostroge s srebrno zvezdasto kolesce." },
    gold_spurs = { name = "Zlate ostroge", goldCost = 1, silverCost = 1, time = 7, cost = 480, cavalryBoost = 18, durability = 50, prestige = 11, happiness = 2, description = "Zlate ostroge za viteze." },
    royal_knight_spurs = { name = "Kraljevski viteške ostroge", goldCost = 2, silverCost = 1, jewelCost = 1, pearlCost = 1, time = 11, cost = 1400, cavalryBoost = 30, durability = 75, prestige = 38, happiness = 8, description = "Velike kraljevske viteške ostroge z dragulji in biseri za kronanje." },
}
local BUILDINGS = {
    workshop = { name = "Ostroška delavnica", cost = { gold = 250, wood = 110 }, upkeep = 6, qualityBonus = 5 },
    forge = { name = "Ostroška kovačija", cost = { gold = 800, wood = 220, stone = 200, iron = 6 }, upkeep = 20, qualityBonus = 18 },
    polishing_room = { name = "Polirnica", cost = { gold = 1800, wood = 280, stone = 400, silver = 25, brass = 8 }, upkeep = 42, qualityBonus = 30 },
    royal_spur_atelier = { name = "Kraljevski atelje ostrog", cost = { gold = 7000, wood = 500, stone = 700, gold = 50, jewel = 20 }, upkeep = 130, qualityBonus = 55, prestigeBonus = 30 },
}
SpurMaker.ironStock = 12; SpurMaker.steelStock = 10; SpurMaker.brassStock = 10; SpurMaker.silverStock = 8; SpurMaker.goldStock = 6; SpurMaker.jewelStock = 6; SpurMaker.pearlStock = 4
SpurMaker.productStock = {}; SpurMaker.buildings = {}; SpurMaker.maker = nil; SpurMaker.activeMaking = {}; SpurMaker.totalProducts = 0; SpurMaker.dayTimer = 0
function SpurMaker.init() SpurMaker.ironStock=12; SpurMaker.steelStock=10; SpurMaker.brassStock=10; SpurMaker.silverStock=8; SpurMaker.goldStock=6; SpurMaker.jewelStock=6; SpurMaker.pearlStock=4; SpurMaker.productStock={}; SpurMaker.buildings={}; SpurMaker.maker=nil; SpurMaker.activeMaking={}; SpurMaker.totalProducts=0; SpurMaker.dayTimer=0; print("[SpurMaker] Royal Spur Maker System initialized (6 products, 4 buildings)") end
function SpurMaker.hireMaker(n,s) s=s or math.random(50,90); local c=470+s*10; if not _G.state or (_G.state.gold or 0)<c then return false,"Premalo zlata" end; _G.state.gold=_G.state.gold-c; SpurMaker.maker={name=n or ("Ostrožar "..math.random(1,99)),skill=s,hiredDay=os.time(),itemsMade=0}; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Ostrožar najet: %s (spretnost: %d)",SpurMaker.maker.name,s),"success") end; return true end
function SpurMaker.canBuild(id) local d=BUILDINGS[id]; if not d then return false,"Neznana zgradba" end; if not _G.state then return false,"Brez stanja" end; if _G.state.gold<(d.cost.gold or 0) then return false,"Premalo zlata" end; if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" and (_G.state.resources[r] or 0)<a then return false,"Premalo "..r end end end; return true end
function SpurMaker.build(id) local ok,e=SpurMaker.canBuild(id); if not ok then return false,e end; local d=BUILDINGS[id]; _G.state.gold=_G.state.gold-(d.cost.gold or 0); if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" then _G.state.resources[r]=(_G.state.resources[r] or 0)-a end end end; table.insert(SpurMaker.buildings,{type=id,builtDay=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,"Zgrajeno: "..d.name,"success") end; return true end
function SpurMaker.getQualityBonus() local b=0; for _,bd in ipairs(SpurMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.qualityBonus then b=b+d.qualityBonus end end; return b end
function SpurMaker.canMake(pt) local d=PRODUCTS[pt]; if not d then return false,"Neznan produkt" end; if d.ironCost and SpurMaker.ironStock<(d.ironCost or 0) then return false,"Premalo železa" end; if d.steelCost and SpurMaker.steelStock<(d.steelCost or 0) then return false,"Premalo jekla" end; if d.brassCost and SpurMaker.brassStock<(d.brassCost or 0) then return false,"Premalo medenine" end; if d.silverCost and SpurMaker.silverStock<(d.silverCost or 0) then return false,"Premalo srebra" end; if d.goldCost and SpurMaker.goldStock<(d.goldCost or 0) then return false,"Premalo zlata" end; if d.jewelCost and SpurMaker.jewelStock<(d.jewelCost or 0) then return false,"Premalo draguljev" end; if d.pearlCost and SpurMaker.pearlStock<(d.pearlCost or 0) then return false,"Premalo biserov" end; if #SpurMaker.buildings==0 then return false,"Potrebna delavnica" end; if not SpurMaker.maker then return false,"Potreben ostrožar" end; return true end
function SpurMaker.make(pt,qty) qty=qty or 1; local ok,e=SpurMaker.canMake(pt); if not ok then return false,e end; local d=PRODUCTS[pt]; if d.ironCost then SpurMaker.ironStock=SpurMaker.ironStock-d.ironCost*qty end; if d.steelCost then SpurMaker.steelStock=SpurMaker.steelStock-d.steelCost*qty end; if d.brassCost then SpurMaker.brassStock=SpurMaker.brassStock-d.brassCost*qty end; if d.silverCost then SpurMaker.silverStock=SpurMaker.silverStock-d.silverCost*qty end; if d.goldCost then SpurMaker.goldStock=SpurMaker.goldStock-d.goldCost*qty end; if d.jewelCost then SpurMaker.jewelStock=SpurMaker.jewelStock-d.jewelCost*qty end; if d.pearlCost then SpurMaker.pearlStock=SpurMaker.pearlStock-d.pearlCost*qty end; local t=d.time; if SpurMaker.maker then t=math.max(1,t-math.floor(SpurMaker.maker.skill/12)) end; table.insert(SpurMaker.activeMaking,{id="spur_"..tostring(os.time()).."_"..tostring(math.random(1000,9999)),productType=pt,productName=d.name,cost=d.cost*qty,quantity=qty,cavalryBoost=d.cavalryBoost or 0,durability=d.durability or 0,prestige=d.prestige or 0,happiness=d.happiness or 0,daysRemaining=t,started=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Izdelava: %d %s (%d dni)",qty,d.name,t),"info") end; return true end
function SpurMaker.completeMaking(m) local q=1.0+(SpurMaker.getQualityBonus()/100); if SpurMaker.maker then q=q+(SpurMaker.maker.skill/180) end; q=math.min(2.0,q); SpurMaker.productStock[m.productType]=(SpurMaker.productStock[m.productType] or 0)+m.quantity; SpurMaker.totalProducts=SpurMaker.totalProducts+m.quantity; if m.prestige>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.prestige) end; if m.happiness>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.happiness) end; if SpurMaker.maker then SpurMaker.maker.itemsMade=SpurMaker.maker.itemsMade+m.quantity; if math.random()<0.20 then SpurMaker.maker.skill=math.min(100,SpurMaker.maker.skill+1) end end; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Ostroge izdelane: %d %s (kakovost: %.1f)",m.quantity,m.productName,q),"success") end; if _G.GameEventBus then pcall(_G.GameEventBus.publish,"spur.completed",{productName=m.productName,cavalryBoost=m.cavalryBoost,durability=m.durability}) end end
function SpurMaker.update(dt) if not _G.state then return end; SpurMaker.dayTimer=SpurMaker.dayTimer+dt; if SpurMaker.dayTimer>=30 then SpurMaker.dayTimer=0; for i=#SpurMaker.activeMaking,1,-1 do local m=SpurMaker.activeMaking[i]; m.daysRemaining=m.daysRemaining-1; if m.daysRemaining<=0 then SpurMaker.completeMaking(m); table.remove(SpurMaker.activeMaking,i) end end; local tu=0; for _,bd in ipairs(SpurMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.upkeep then tu=tu+d.upkeep end end; if SpurMaker.maker then tu=tu+13 end; if tu>0 and _G.state then _G.state.gold=math.max(0,(_G.state.gold or 0)-tu) end end end
function SpurMaker.getStats() return {ironStock=SpurMaker.ironStock,steelStock=SpurMaker.steelStock,brassStock=SpurMaker.brassStock,silverStock=SpurMaker.silverStock,goldStock=SpurMaker.goldStock,jewelStock=SpurMaker.jewelStock,pearlStock=SpurMaker.pearlStock,productStock=SpurMaker.productStock,numBuildings=#SpurMaker.buildings,hasMaker=SpurMaker.maker~=nil,makerName=SpurMaker.maker and SpurMaker.maker.name or "—",makerSkill=SpurMaker.maker and SpurMaker.maker.skill or 0,activeMaking=#SpurMaker.activeMaking,totalProducts=SpurMaker.totalProducts} end
return SpurMaker
